"""Real loopback HTTP and source-bundle/config interoperability tests."""
import hashlib,io,json,tempfile,threading,unittest,zipfile
from http.server import BaseHTTPRequestHandler,ThreadingHTTPServer
from pathlib import Path
import numpy as np,onnxruntime as ort
from coremltools.proto import MIL_pb2
from test_convert_model import nn_spec,mil_spec,mil_const,mil_op,feature,tensor
from convert_model import convert,Unsupported
from model_metadata import convert_with_metadata,read_metadata
from model_catalog import fetch_catalog,source_url,convert_catalog_model,available_models,catalog_with_cache
from unittest.mock import patch

class CatalogTests(unittest.TestCase):
    def setUp(self):self.temp=tempfile.TemporaryDirectory();self.root=Path(self.temp.name)
    def tearDown(self):self.temp.cleanup()
    def write(self,spec,name='source.mlmodel'):path=self.root/name;path.write_bytes(spec.SerializeToString());return path
    def test_source_sidecar_preserves_original_index_config_and_catalog_identity(self):
        spec=nn_spec();spec.description.input[0].type.multiArrayType.shape[:]=[1,3,3,3];spec.description.output[0].type.multiArrayType.shape[:]=[1,3,15,15];spec.neuralNetwork.layers[-1].upsample.scalingFactor[:]=[5,5];source=self.write(spec);info={'name':'五倍模型','file':'models/original.mlmodel','type':'multiarray','version':7,'info':'Original notes','tags':['5x'],'config':{'blockSize':3,'scale':5,'shrinkSize':0,'inputName':'input','outputName':'output','preserveGrayscale':False},'unknown':{'keep':[1,2]}};Path(str(source)+'.json').write_text(json.dumps(info),encoding='utf8');report=convert_with_metadata(source,self.root/'out');self.assertEqual(report['scale'],5);self.assertEqual(report['catalogFile'],'original.mlmodel');self.assertEqual(report['sourceFile'],'models/original.mlmodel');self.assertEqual(report['config'],info['config']);self.assertEqual(report['version'],7);self.assertEqual(report['unknown'],info['unknown']);self.assertTrue(report['inputHalfStep']);self.assertFalse(report['preserveGrayscale'])
    def test_nested_android_raw_package_bundle_with_model_json_is_convertible(self):
        inner=io.BytesIO()
        with zipfile.ZipFile(inner,'w') as archive:archive.writestr('Source.mlpackage/Data/com.apple.CoreML/model.mlmodel',nn_spec().SerializeToString())
        bundle=self.root/'source.aidoku-coreml.zip';info={'name':'Exported model','file':'source.mlpackage.zip','catalogFile':'original.mlpackage','sourceFile':'models/original.mlpackage','version':3,'type':'multiarray','config':{'blockSize':16,'scale':2}}
        with zipfile.ZipFile(bundle,'w') as archive:archive.writestr('source.mlpackage.zip',inner.getvalue());archive.writestr('model.json',json.dumps(info))
        report=convert_with_metadata(bundle,self.root/'out');self.assertEqual(report['catalogFile'],'original.mlpackage');self.assertEqual(report['version'],3);self.assertTrue(report['appCompatible']);self.assertEqual(report['outputShape'],[1,3,32,32]);self.assertTrue((self.root/'out/Exportedmodel.aidoku-model.zip').exists())
    def test_actual_http_catalog_source_download_conversion_and_version_updates(self):
        source=nn_spec().SerializeToString();requests=[];info={'name':'HTTP model','file':'models/live.mlmodel','version':2,'type':'multiarray','sha256':hashlib.sha256(source).hexdigest(),'config':{'blockSize':16,'scale':2},'tags':['fast']}
        class Handler(BaseHTTPRequestHandler):
            def do_GET(handler):
                requests.append((handler.path,handler.headers.get('User-Agent')));payload=json.dumps({'models':[info,{'type':None,'file':'unknown'}]}).encode() if handler.path=='/models.json' else source;handler.send_response(200);handler.send_header('Content-Length',str(len(payload)));handler.end_headers();handler.wfile.write(payload)
            def log_message(*args):pass
        server=ThreadingHTTPServer(('127.0.0.1',0),Handler);thread=threading.Thread(target=server.serve_forever,daemon=True);thread.start()
        try:
            address=f'http://127.0.0.1:{server.server_port}/models.json';models=fetch_catalog(address);self.assertEqual(len(models),1);self.assertEqual(available_models(models,self.root/'out'),models);report=convert_catalog_model(address,models[0],self.root/'out');self.assertEqual(report['downloadSha256'],info['sha256']);self.assertEqual(report['catalogFile'],'live.mlmodel');self.assertEqual(report['version'],2);self.assertEqual(available_models(models,self.root/'out'),[]);models[0]['version']=3;self.assertEqual(available_models(models,self.root/'out'),models);self.assertEqual([path for path,_ in requests],['/models.json','/models/live.mlmodel']);self.assertTrue(all('Aidoku' in ua for _,ua in requests))
        finally:server.shutdown();server.server_close();thread.join()
    def test_package_download_suffix_keeps_query_and_metadata_size_limits(self):
        self.assertEqual(source_url('http://example.com/catalog/models.json',{'file':'../models/test.mlpackage?version=2'}),'http://example.com/models/test.mlpackage.zip?version=2');source=self.write(nn_spec());Path(str(source)+'.json').write_bytes(b' '*1048577)
        with self.assertRaisesRegex(ValueError,'exceeds'):read_metadata(source)
    def test_source_bundle_rejects_ambiguous_metadata_and_unsafe_inner_archive(self):
        bundle=self.root/'bad.zip'
        with zipfile.ZipFile(bundle,'w') as archive:archive.writestr('source.mlmodel',nn_spec().SerializeToString());archive.writestr('model.json','{}');archive.writestr('model.json','{}')
        with self.assertRaisesRegex(ValueError,'duplicate'):read_metadata(bundle)
        inner=io.BytesIO()
        with zipfile.ZipFile(inner,'w') as archive:archive.writestr('../escape.mlmodel',nn_spec().SerializeToString())
        with zipfile.ZipFile(bundle,'w') as archive:archive.writestr('source.mlpackage.zip',inner.getvalue());archive.writestr('model.json','{}')
        with self.assertRaisesRegex(Unsupported,'unsafe'):convert_with_metadata(bundle,self.root/'out')
    def test_configured_output_and_optional_default_input_follow_original_prediction_contract(self):
        spec=nn_spec();network=spec.neuralNetwork;del network.layers[:];feature(spec,'offset',[1]);spec.description.input[-1].type.isOptional=True;spec.description.input[-1].type.multiArrayType.floatDefaultValue=0.25;feature(spec,'chosen',[1,3,16,16],True);l=network.layers.add();l.name='ignored';l.input.append('input');l.output.append('output');l.copy.SetInParent();l=network.layers.add();l.name='selected';l.input.extend(['input','offset']);l.output.append('chosen');l.add.SetInParent();report=convert_with_metadata(self.write(spec),self.root/'out','selected',{'type':'multiarray','config':{'blockSize':16,'scale':1,'inputName':'input','outputName':'chosen'}});self.assertEqual(report['outputShape'],[1,3,16,16]);data=np.random.default_rng(59).random((1,3,16,16),dtype=np.float32);session=ort.InferenceSession(str(self.root/'out/selected.onnx'));np.testing.assert_array_equal(session.run(None,{report['inputName']:data})[0],data+0.25)
    def test_mil_inverse_hyperbolic_and_exp2_public_branches_match_numpy(self):
        spec=mil_spec();block=spec.mlProgram.functions['main'].block_specializations['CoreML5'];del block.operations[:];mil_const(block,'half',0.5);mil_op(block,'mul','smaller',{'x':'input','y':'half'},[1,3,16,16]);mil_op(block,'atanh','inverse',{'x':'smaller'},[1,3,16,16]);mil_op(block,'exp2','output',{'x':'inverse'},[1,3,16,16]);report=convert(self.write(spec),self.root/'out','unary');data=np.random.default_rng(60).random((1,3,16,16),dtype=np.float32);np.testing.assert_allclose(ort.InferenceSession(str(self.root/'out/unary.onnx')).run(None,{report['inputName']:data})[0],np.exp2(np.arctanh(data*0.5)),rtol=1e-6,atol=1e-7)
    def test_unsigned_mil_casts_retain_integer_truncation_semantics(self):
        for datatype,dtype in [('uint16',MIL_pb2.UINT16),('uint32',MIL_pb2.UINT32),('uint64',MIL_pb2.UINT64)]:
            spec=mil_spec();block=spec.mlProgram.functions['main'].block_specializations['CoreML5'];del block.operations[:];mil_const(block,'scale',257.0);mil_const(block,'to_unsigned',datatype,MIL_pb2.STRING);mil_const(block,'to_float','fp32',MIL_pb2.STRING);mil_op(block,'mul','scaled',{'x':'input','y':'scale'},[1,3,16,16]);mil_op(block,'cast','integers',{'x':'scaled','dtype':'to_unsigned'},[1,3,16,16],dtype);mil_op(block,'cast','output',{'x':'integers','dtype':'to_float'},[1,3,16,16]);report=convert(self.write(spec),self.root/'out',datatype);data=np.random.default_rng(61).random((1,3,16,16),dtype=np.float32);np.testing.assert_array_equal(ort.InferenceSession(str(self.root/f'out/{datatype}.onnx')).run(None,{report['inputName']:data})[0],np.trunc(data*257))
    def test_empty_nn_loop_is_validated_then_eliminated_without_outputs(self):
        spec=nn_spec();network=spec.neuralNetwork;del network.layers[:];loop=network.layers.add();loop.name='finite_empty';loop.loop.maxLoopIterations=3;copy=network.layers.add();copy.name='result';copy.input.append('input');copy.output.append('output');copy.copy.SetInParent();report=convert(self.write(spec),self.root/'out','emptyloop');data=np.random.default_rng(62).random((1,3,16,16),dtype=np.float32);np.testing.assert_array_equal(ort.InferenceSession(str(self.root/'out/emptyloop.onnx')).run(None,{report['inputName']:data})[0],data)
    def test_nn_reduce_all_retains_rank_one_used_by_downstream_get_shape(self):
        for axes,all_flag in [([],True),([0,1,2,3],False),([],False)]:
            spec=nn_spec();network=spec.neuralNetwork;network.arrayInputShapeMapping=1;del network.layers[:]
            def layer(kind,inputs,outputs):l=network.layers.add();l.name=kind;l.input.extend(inputs);l.output.extend(outputs);return getattr(l,kind)
            p=layer('reduceMean',['input'],['mean']);p.axes.extend(axes);p.reduceAll=all_flag;p.keepDims=False;layer('getShape',['mean'],['rank_shape']).SetInParent();layer('add',['mean','rank_shape'],['offset']).SetInParent();layer('add',['input','offset'],['output']).SetInParent();report=convert(self.write(spec),self.root/'out','rankone');data=np.random.default_rng(63).random((1,3,16,16),dtype=np.float32);np.testing.assert_allclose(ort.InferenceSession(str(self.root/'out/rankone.onnx')).run(None,{report['inputName']:data})[0],data+data.mean()+1,rtol=1e-6,atol=1e-7)
    def test_nn_documented_unset_defaults_and_training_metadata_are_inferable(self):
        spec=nn_spec();spec.isUpdatable=True;network=spec.neuralNetwork;del network.layers[:]
        def layer(kind,inputs,outputs):l=network.layers.add();l.name=kind;l.input.extend(inputs);l.output.extend(outputs);return getattr(l,kind)
        p=layer('unary',['input'],['root']);p.type=1;layer('upsample',['root'],['same']).SetInParent();layer('reshapeStatic',['same'],['five']).targetShape.extend([1,1,3,16,16]);layer('sequenceRepeat',['five'],['repeat']).SetInParent();layer('reshapeStatic',['repeat'],['restored']).targetShape.extend([1,3,16,16]);layer('resizeBilinear',['restored'],['small']).SetInParent();layer('broadcastToLike',['small','input'],['output']).SetInParent();report=convert(self.write(spec),self.root/'out','defaults');data=np.random.default_rng(64).random((1,3,16,16),dtype=np.float32);expected=np.broadcast_to((1/np.sqrt(data[:,:,0:1,0:1]+np.float32(1e-6))),data.shape);np.testing.assert_allclose(ort.InferenceSession(str(self.root/'out/defaults.onnx')).run(None,{report['inputName']:data})[0],expected,rtol=1e-6,atol=1e-7)
    def test_nn_same_top_left_pooling_and_default_last_pixel_padding(self):
        for padding in ('same','includeLastPixel'):
            spec=nn_spec();network=spec.neuralNetwork;del network.layers[:];l=network.layers.add();l.name='pool';l.input.append('input');l.output.append('pooled');p=l.pooling;p.type=0;p.kernelSize.extend([3,3]);p.stride.extend([2,2]);getattr(p,padding).SetInParent()
            if padding=='same':p.same.asymmetryMode=1
            l=network.layers.add();l.name='up';l.input.append('pooled');l.output.append('output');l.upsample.scalingFactor.extend([2,2]);report=convert(self.write(spec),self.root/'out',padding);data=np.random.default_rng(65).random((1,3,16,16),dtype=np.float32);padded=np.pad(data,[(0,0),(0,0),(1,0),(1,0)],constant_values=-np.inf) if padding=='same' else np.pad(data,[(0,0),(0,0),(0,1),(0,1)],constant_values=-np.inf);expected=np.stack([padded[:,:,y:y+3,x:x+3].max(axis=(2,3)) for y in range(0,16,2) for x in range(0,16,2)],axis=-1).reshape(1,3,8,8);np.testing.assert_array_equal(ort.InferenceSession(str(self.root/f'out/{padding}.onnx')).run(None,{report['inputName']:data})[0],np.repeat(np.repeat(expected,2,2),2,3))
    def test_mil_nearest_resize_offset_and_singleton_align_sample_positions(self):
        for mode,target in [('OFFSET_CORNERS',[32,32]),('ALIGN_CORNERS',[1,32])]:
            spec=mil_spec();block=spec.mlProgram.functions['main'].block_specializations['CoreML5'];del block.operations[:];mil_const(block,'target',target,MIL_pb2.INT32);mil_const(block,'dims',2,MIL_pb2.UINT32);mil_const(block,'sampling',mode,MIL_pb2.STRING);mil_const(block,'interpolation','NEAREST_NEIGHBOR',MIL_pb2.STRING);mil_op(block,'resize','output',{'x':'input','shape':'target','resized_dims':'dims','sampling_mode':'sampling','interpolation_mode':'interpolation'},[1,3]+target);report=convert(self.write(spec),self.root/'out','nearest',allow_general=target[0]==1);data=np.random.default_rng(66).random((1,3,16,16),dtype=np.float32);ys=np.floor((np.arange(target[0])+0.5)*15/target[0]).astype(int) if mode=='OFFSET_CORNERS' else np.array([7]);xs=np.floor((np.arange(32)+0.5)*15/32).astype(int) if mode=='OFFSET_CORNERS' else np.floor(np.linspace(0,15,32)).astype(int);expected=data[:,:,ys,:][:,:,:,xs];np.testing.assert_array_equal(ort.InferenceSession(str(self.root/'out/nearest.onnx')).run(None,{report['inputName']:data})[0],expected)
    def test_nn_zero_epsilon_defaults_produce_finite_zero_tensor(self):
        for operator in ('batchnorm','mvn','l2normalize'):
            spec=nn_spec();network=spec.neuralNetwork;del network.layers[:];l=network.layers.add();l.name=operator;l.input.append('input');l.output.append('output');p=getattr(l,operator);p.SetInParent()
            if operator=='batchnorm':
                p.channels=3;p.gamma.floatValue.extend([1]*3)
                for weights in (p.beta,p.mean,p.variance):weights.floatValue.extend([0]*3)
            if operator=='mvn':p.normalizeVariance=True
            report=convert(self.write(spec),self.root/'out',operator);data=np.zeros((1,3,16,16),dtype=np.float32);np.testing.assert_array_equal(ort.InferenceSession(str(self.root/f'out/{operator}.onnx')).run(None,{report['inputName']:data})[0],data)
    def test_catalog_cache_reports_staleness_and_preserves_versions_after_network_failure(self):
        cache=self.root/'catalog.json';address='http://example.test/models.json';models=[{'file':'models/model.mlmodel','type':'multiarray','version':4}]
        with patch('model_catalog.fetch_catalog',return_value=models):self.assertEqual(catalog_with_cache(address,cache),(models,False,None))
        with patch('model_catalog.fetch_catalog',side_effect=OSError('network offline')):
            cached,stale,error=catalog_with_cache(address,cache);self.assertEqual(cached,models);self.assertTrue(stale);self.assertEqual(error,'network offline')
        cached,stale,error=catalog_with_cache(address,cache,True);self.assertEqual(cached,models);self.assertTrue(stale);self.assertIn('explicitly',error)
    def test_catalog_cache_never_crosses_directory_url_or_accepts_malformed_data(self):
        cache=self.root/'catalog.json';cache.write_text(json.dumps({'catalog':'http://old.test/models.json','models':[{'file':'test.mlmodel','type':'multiarray'}]}),encoding='utf8')
        with patch('model_catalog.fetch_catalog',side_effect=OSError('unavailable')):
            with self.assertRaisesRegex(OSError,'unavailable'):catalog_with_cache('http://new.test/models.json',cache)
            cache.write_bytes(b' '*2097153)
            with self.assertRaisesRegex(OSError,'unavailable'):catalog_with_cache('http://old.test/models.json',cache)
    def test_original_image_model_ignores_multiarray_config_but_preserves_metadata(self):
        spec=nn_spec(image=True);metadata={'type':'image','name':'Image original','version':3,'config':{'inputName':'unused_input','outputName':'unused_output','shape':[1,3,9,9],'blockSize':9,'scale':5,'shrinkSize':4,'tileOverlap':200,'preserveGrayscale':True}};report=convert_with_metadata(self.write(spec),self.root/'out',metadata=metadata);self.assertEqual(report['processingMode'],'image');self.assertEqual(report['inputShape'],[1,3,16,16]);self.assertEqual(report['outputShape'],[1,3,32,32]);self.assertEqual(report['config'],metadata['config']);self.assertEqual(report['tileOverlap'],0);self.assertFalse(report['preserveGrayscale']);self.assertFalse(report['inputHalfStep'])
    def test_mil_runtime_padding_values_depend_on_image_and_keep_fixed_pixel_output(self):
        spec=mil_spec();block=spec.mlProgram.functions['main'].block_specializations['CoreML5'];del block.operations[:];mil_const(block,'axes',[0,1,2,3],MIL_pb2.INT32);mil_const(block,'half',0.5);mil_const(block,'one',[1,1,1,1],MIL_pb2.INT32);mil_const(block,'int','int32',MIL_pb2.STRING);mil_op(block,'reduce_mean','mean',{'x':'input','axes':'axes'},[]);mil_op(block,'greater','greater',{'x':'mean','y':'half'},[],MIL_pb2.BOOL);mil_op(block,'cast','flag',{'x':'greater','dtype':'int'},[],MIL_pb2.INT32);mil_op(block,'add','amounts',{'x':'one','y':'flag'},[4],MIL_pb2.INT32);mil_op(block,'pad','padded',{'x':'input','pad':'amounts'},[1,3,20,20]);mil_const(block,'begin',[0,0,0,0],MIL_pb2.INT32);mil_const(block,'end',[1,3,16,16],MIL_pb2.INT32);mil_op(block,'slice_by_index','output',{'x':'padded','begin':'begin','end':'end'},[1,3,16,16]);report=convert(self.write(spec),self.root/'out','runtimepad');session=ort.InferenceSession(str(self.root/'out/runtimepad.onnx'))
        for offset in (0.0,0.6):
            data=np.random.default_rng(67).random((1,3,16,16),dtype=np.float32)*0.3+offset;amount=1+int(data.mean()>0.5);expected=np.pad(data,[(0,0),(0,0),(amount,amount),(amount,amount)])[:,:,:16,:16];np.testing.assert_array_equal(session.run(None,{report['inputName']:data})[0],expected)
    def test_mil_runtime_tile_repetitions_are_not_assumed_constant(self):
        spec=mil_spec();block=spec.mlProgram.functions['main'].block_specializations['CoreML5'];del block.operations[:];mil_const(block,'axes',[0,1,2,3],MIL_pb2.INT32);mil_const(block,'half',0.5);mil_const(block,'one',[1,1,1,1],MIL_pb2.INT32);mil_const(block,'last',[0,0,0,1],MIL_pb2.INT32);mil_const(block,'int','int32',MIL_pb2.STRING);mil_op(block,'reduce_mean','mean',{'x':'input','axes':'axes'},[]);mil_op(block,'greater','greater',{'x':'mean','y':'half'},[],MIL_pb2.BOOL);mil_op(block,'cast','flag',{'x':'greater','dtype':'int'},[],MIL_pb2.INT32);mil_op(block,'mul','extra',{'x':'last','y':'flag'},[4],MIL_pb2.INT32);mil_op(block,'add','reps',{'x':'one','y':'extra'},[4],MIL_pb2.INT32);mil_op(block,'tile','tiled',{'x':'input','reps':'reps'},[1,3,16,32]);mil_const(block,'eight',8,MIL_pb2.INT32);mil_op(block,'mul','begin',{'x':'extra','y':'eight'},[4],MIL_pb2.INT32);mil_const(block,'size',[1,3,16,16],MIL_pb2.INT32);mil_op(block,'add','end',{'x':'begin','y':'size'},[4],MIL_pb2.INT32);mil_op(block,'slice_by_index','output',{'x':'tiled','begin':'begin','end':'end'},[1,3,16,16]);report=convert(self.write(spec),self.root/'out','runtimetile');session=ort.InferenceSession(str(self.root/'out/runtimetile.onnx'))
        for offset in (0.0,0.6):
            data=np.random.default_rng(68).random((1,3,16,16),dtype=np.float32)*0.3+offset;flag=int(data.mean()>0.5);start=8*flag;expected=np.tile(data,[1,1,1,1+flag])[:,:,:,start:start+16];np.testing.assert_array_equal(session.run(None,{report['inputName']:data})[0],expected)
    def test_symbolic_mil_list_element_dimensions_resolve_on_first_write(self):
        for initial_length in (0,2):
            spec=mil_spec();block=spec.mlProgram.functions['main'].block_specializations['CoreML5'];del block.operations[:];mil_const(block,'initial',initial_length,MIL_pb2.INT32);mil_const(block,'index',1,MIL_pb2.INT32);mil_const(block,'axis',[0],MIL_pb2.INT32);mil_const(block,'channels',3,MIL_pb2.INT32);mil_const(block,'height','symbol_height',MIL_pb2.STRING);mil_const(block,'width','symbol_width',MIL_pb2.STRING);mil_const(block,'two',2.0)
            def list_op(kind,name,args):
                op=mil_op(block,kind,name,args,[]);out=op.outputs[0];out.type.ClearField('tensorType');tensor(out.type.listType.type,MIL_pb2.FLOAT32,[3,16,16])
                for dim in out.type.listType.type.tensorType.dimensions[1:]:dim.ClearField('constant');dim.unknown.SetInParent()
            list_op('make_list','empty',{'init_length':'initial','elem_shape':['channels','height','width']});mil_op(block,'squeeze','element',{'x':'input','axes':'axis'},[3,16,16]);list_op('list_write','written',{'ls':'empty','index':'index','value':'element'});mil_op(block,'mul','changed',{'x':'element','y':'two'},[3,16,16]);list_op('list_write','replaced',{'ls':'written','index':'index','value':'changed'});mil_op(block,'list_read','read',{'ls':'replaced','index':'index'},[3,16,16]);mil_op(block,'expand_dims','output',{'x':'read','axes':'axis'},[1,3,16,16]);report=convert(self.write(spec),self.root/'out','symboliclist');data=np.random.default_rng(69).random((1,3,16,16),dtype=np.float32);np.testing.assert_array_equal(ort.InferenceSession(str(self.root/'out/symboliclist.onnx')).run(None,{report['inputName']:data})[0],data*2)
    def test_fixed_length_mil_list_write_cannot_silently_grow(self):
        spec=mil_spec();block=spec.mlProgram.functions['main'].block_specializations['CoreML5'];del block.operations[:];mil_const(block,'initial',2,MIL_pb2.INT32);mil_const(block,'index',1,MIL_pb2.INT32);mil_const(block,'axis',[0],MIL_pb2.INT32);mil_const(block,'channels',3,MIL_pb2.INT32);mil_const(block,'side',16,MIL_pb2.INT32);mil_const(block,'fixed',False,MIL_pb2.BOOL)
        def list_op(kind,name,args):op=mil_op(block,kind,name,args,[]);out=op.outputs[0];out.type.ClearField('tensorType');tensor(out.type.listType.type,MIL_pb2.FLOAT32,[3,16,16])
